WITH c0 AS (SELECT rel_path,source_version FROM (SELECT rel_path, line, item_key, source_version, namespace FROM facts WHERE predicate = 'fixture.key' AND value = 'al' AND line IS NULL AND item_key IS NULL) WHERE namespace IN (SELECT value FROM json_each('["fixture"]')) AND line IS NULL AND item_key IS NULL),g1 AS (SELECT rel_path,source_version FROM c0),c2 AS (SELECT rel_path,source_version FROM (SELECT rel_path, line, item_key, source_version, namespace FROM facts WHERE predicate = 'fixture.key' AND gilune_fold(value) >= 'al' AND gilune_fold(value) < 'am' AND line IS NULL AND item_key IS NULL) WHERE namespace IN (SELECT value FROM json_each('["fixture"]')) AND line IS NULL AND item_key IS NULL),g3 AS (SELECT rel_path,source_version FROM c2),c4 AS (SELECT rel_path,source_version FROM (SELECT rel_path, line, item_key, source_version, namespace FROM facts WHERE predicate = 'fixture.name' AND gilune_fold(value) >= 'al' AND gilune_fold(value) < 'am' AND line IS NULL AND item_key IS NULL) WHERE namespace IN (SELECT value FROM json_each('["fixture"]')) AND line IS NULL AND item_key IS NULL),g5 AS (SELECT rel_path,source_version FROM c4),alternatives AS (SELECT rel_path,source_version,0 AS priority FROM g1 UNION ALL SELECT rel_path,source_version,1 AS priority FROM g3 UNION ALL SELECT rel_path,source_version,2 AS priority FROM g5),candidates AS MATERIALIZED (SELECT rel_path,source_version,MIN(priority) AS priority FROM alternatives GROUP BY rel_path,source_version),matched AS MATERIALIZED (SELECT b.* FROM candidates b CROSS JOIN source_maps u ON u.rel_path=b.rel_path AND u.source_version=b.source_version WHERE EXISTS (SELECT 1 FROM (SELECT rel_path, line, item_key, source_version, namespace FROM facts INDEXED BY facts_path WHERE predicate = 'fixture.kind' AND value = 'entry' AND line IS NULL AND item_key IS NULL) f WHERE f.rel_path=u.rel_path AND f.source_version=u.source_version AND f.namespace IN (SELECT value FROM json_each('["fixture"]'))) AND EXISTS (SELECT 1 FROM fact_sources r WHERE r.rel_path=u.rel_path AND r.source_version=u.source_version AND r.namespace='fixture')),ranked AS (SELECT m.*,MIN(CASE WHEN f.predicate='fixture.name' THEN f.value END) AS s0,MIN(CASE WHEN f.predicate='fixture.key' THEN f.value END) AS s1 FROM matched m LEFT JOIN facts f ON f.rel_path=m.rel_path AND f.source_version=m.source_version AND f.line IS NULL AND f.item_key IS NULL AND f.namespace IN (SELECT value FROM json_each('["fixture"]')) AND f.predicate IN (SELECT value FROM json_each('["fixture.name","fixture.key"]')) GROUP BY m.rel_path,m.source_version,m.priority) SELECT rel_path,source_version,priority,COUNT(*) OVER() FROM ranked WHERE priority < 4294967296 ORDER BY priority,s0 IS NULL,s0,s1 IS NULL,s1,rel_path LIMIT 30 OFFSET 0